<?php
declare(strict_types=1);

final class InvestmentController
{
    public function index(): void
    {
        $user=require_auth();$uid=(int)$user['id'];$items=InvestmentService::all($uid);$db=Database::connection();$history=[];$edit=null;
        if(isset($_GET['history'])){$stmt=$db->prepare('SELECT t.*,i.name AS investment_name FROM investment_transactions t JOIN investments i ON i.id=t.investment_id AND i.user_id=t.user_id WHERE t.user_id=:user AND t.investment_id=:investment ORDER BY t.movement_date DESC,t.id DESC');$stmt->execute(['user'=>$uid,'investment'=>(int)$_GET['history']]);$history=$stmt->fetchAll();}
        if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM investments WHERE user_id=:user AND id=:id');$stmt->execute(['user'=>$uid,'id'=>(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}
        $totalMarket=array_sum(array_map(fn($item)=>(int)$item['market_value'],$items));$totalInvested=array_sum(array_map(fn($item)=>(int)$item['cost_basis'],$items));
        render('investments/index',['title'=>'Investimentos','items'=>$items,'edit'=>$edit,'history'=>$history,'totalMarket'=>$totalMarket,'totalInvested'=>$totalInvested,'types'=>InvestmentService::TYPES,'errors'=>$_SESSION['_errors']??[]]);unset($_SESSION['_errors']);
    }
    public function save(): void
    {
        $user=require_auth();verify_csrf();$db=Database::connection();$uid=(int)$user['id'];$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['type']??'');$institution=trim((string)($_POST['institution']??''));$quantity=self::quantity((string)($_POST['quantity']??'0'));$average=FinancialService::moneyToCents((string)($_POST['average_price']??'0'));$invested=FinancialService::moneyToCents((string)($_POST['invested_amount']??''));$market=FinancialService::moneyToCents((string)($_POST['market_value']??''));$date=(string)($_POST['application_date']??'');$notes=trim((string)($_POST['notes']??''));$errors=[];
        if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Informe um nome de ativo entre 2 e 100 caracteres.';if(!isset(InvestmentService::TYPES[$type]))$errors[]='Selecione o tipo de investimento.';if(mb_strlen($institution)>100||mb_strlen($notes)>500)$errors[]='Revise os limites dos campos de instituição e observações.';if($quantity===null||$quantity<0)$errors[]='Informe uma quantidade válida.';if($average===null||$average<0||$invested===null||$invested<0||$market===null||$market<0)$errors[]='Informe valores monetários válidos.';if(!FinancialService::validDate($date))$errors[]='Informe uma data de aplicação válida.';
        if($errors){$_SESSION['_errors']=$errors;redirect('/investments'.($id?'?edit='.$id:''));}$now=gmdate('c');
        if($id){$stmt=$db->prepare('UPDATE investments SET name=:name,type=:type,institution=:institution,quantity_micros=:quantity,average_price=:average,invested_amount=:invested,market_value=:market,application_date=:date,notes=:notes,updated_at=:at WHERE id=:id AND user_id=:user');$stmt->execute(['name'=>$name,'type'=>$type,'institution'=>$institution,'quantity'=>$quantity,'average'=>$average,'invested'=>$invested,'market'=>$market,'date'=>$date,'notes'=>$notes,'at'=>$now,'id'=>$id,'user'=>$uid]);}
        else{$db->beginTransaction();try{$stmt=$db->prepare('INSERT INTO investments(user_id,name,type,institution,quantity_micros,average_price,invested_amount,market_value,application_date,notes,created_at,updated_at) VALUES(:user,:name,:type,:institution,:quantity,:average,:invested,:market,:date,:notes,:created,:updated)');$stmt->execute(['user'=>$uid,'name'=>$name,'type'=>$type,'institution'=>$institution,'quantity'=>$quantity,'average'=>$average,'invested'=>$invested,'market'=>$market,'date'=>$date,'notes'=>$notes,'created'=>$now,'updated'=>$now]);$id=(int)$db->lastInsertId();if($invested>0){$db->prepare("INSERT INTO investment_transactions(user_id,investment_id,kind,amount,quantity_micros,movement_date,notes,created_at) VALUES(:user,:investment,'application',:amount,:quantity,:date,'Valor inicial cadastrado',:at)")->execute(['user'=>$uid,'investment'=>$id,'amount'=>$invested,'quantity'=>$quantity,'date'=>$date,'at'=>$now]);}$db->commit();}catch(Throwable $error){$db->rollBack();throw $error;}}
        redirect('/investments');
    }
    public function movement(): void
    {
        $user=require_auth();verify_csrf();$db=Database::connection();$uid=(int)$user['id'];$id=(int)($_POST['investment_id']??0);$kind=(string)($_POST['kind']??'');$amount=FinancialService::moneyToCents((string)($_POST['amount']??''));$date=(string)($_POST['movement_date']??'');$notes=trim((string)($_POST['notes']??''));$stmt=$db->prepare('SELECT * FROM investments WHERE id=:id AND user_id=:user AND is_active=1');$stmt->execute(['id'=>$id,'user'=>$uid]);$item=$stmt->fetch();$errors=[];if(!$item)$errors[]='Ativo não encontrado ou inativo.';if(!in_array($kind,['application','redemption','income','valuation'],true))$errors[]='Selecione um tipo de movimentação válido.';if($amount===null||$amount<=0)$errors[]='Informe um valor maior que zero.';if(!FinancialService::validDate($date))$errors[]='Informe uma data válida.';if(mb_strlen($notes)>300)$errors[]='As observações devem ter até 300 caracteres.';
        if($item&&$amount!==null){if($kind==='redemption'&&$amount>(int)$item['invested_amount'])$errors[]='O resgate não pode exceder o valor investido.';if($kind==='valuation'&&$amount===0)$errors[]='Informe o valor atual do ativo.';}
        if($errors){$_SESSION['_errors']=$errors;redirect('/investments?history='.$id);}$db->beginTransaction();try{$quantity=(int)$item['quantity_micros'];$invested=(int)$item['invested_amount'];$market=(int)$item['market_value'];
            if($kind==='application'){$invested+=$amount;$market+=$amount;if((int)$item['average_price']>0)$quantity+=(int)round($amount*1000000/(int)$item['average_price']);}
            elseif($kind==='redemption'){$quantity=max(0,$quantity-(int)round($quantity*$amount/max(1,$invested)));$invested-=$amount;$market=max(0,$market-$amount);}
            elseif($kind==='income')$market+=$amount;else $market=$amount;
            $db->prepare('UPDATE investments SET quantity_micros=:quantity,invested_amount=:invested,market_value=:market,updated_at=:at WHERE id=:id AND user_id=:user')->execute(['quantity'=>$quantity,'invested'=>$invested,'market'=>$market,'at'=>gmdate('c'),'id'=>$id,'user'=>$uid]);$db->prepare('INSERT INTO investment_transactions(user_id,investment_id,kind,amount,quantity_micros,movement_date,notes,created_at) VALUES(:user,:investment,:kind,:amount,:quantity,:date,:notes,:at)')->execute(['user'=>$uid,'investment'=>$id,'kind'=>$kind,'amount'=>$amount,'quantity'=>$kind==='application'?(int)round($amount*1000000/max(1,(int)$item['average_price'])):0,'date'=>$date,'notes'=>$notes,'at'=>gmdate('c')]);$db->commit();
        }catch(Throwable $error){$db->rollBack();throw $error;}redirect('/investments?history='.$id);
    }
    public function archive(): void { $user=require_auth();verify_csrf();$db=Database::connection();$db->prepare('UPDATE investments SET is_active=1-is_active,updated_at=:at WHERE id=:id AND user_id=:user')->execute(['at'=>gmdate('c'),'id'=>(int)($_POST['id']??0),'user'=>$user['id']]);redirect('/investments'); }
    private static function quantity(string $value): ?int { $value=trim(str_replace(',','.',$value));if(!preg_match('/^\d{1,12}(?:\.\d{1,6})?$/',$value))return null;$number=(float)$value;if($number>1000000000)return null;return (int)round($number*1000000); }
}
